const data = msg.payload;

const registry = {
    "cc-01": "gudang-a",
    "cc-02": "gudang-a",
    "cc-03": "gudang-b"
};

function reject(reason) {
    node.warn("Telemetry ditolak: " + reason);
    return null;
}

// 1. Validasi payload
if (!data || typeof data !== "object") {
    return reject("Payload tidak valid");
}

// 2. Validasi schema
if (data.schema !== "kampus.telemetry.v1") {
    return reject("Schema tidak dikenal");
}

// 3. Validasi device registry
if (!Object.prototype.hasOwnProperty.call(
    registry, data.device_id
)) {
    return reject("Device tidak terdaftar");
}

// 4. Validasi lokasi
if (
    data.domain !== "coldchain" ||
    data.gedung !== "bsd-a" ||
    data.ruang !== registry[data.device_id]
) {
    return reject("Lokasi tidak sesuai registry");
}

// 5. Validasi MQTT topic
const expectedTopic =
    `kampus/coldchain/bsd-a/${data.ruang}/${data.device_id}/telemetry`;

if (msg.topic !== expectedTopic) {
    return reject("MQTT topic tidak sesuai");
}

// 6. Validasi timestamp
if (
    !Number.isSafeInteger(data.ts) ||
    data.ts <= 0
) {
    return reject("Timestamp tidak valid");
}

// 7. Validasi metrics
const m = data.metrics;

if (!m || typeof m !== "object") {
    return reject("Metrics tidak tersedia");
}

const numericFields = [
    "temp_c",
    "humidity_pct",
    "battery_pct",
    "rssi_dbm"
];

for (const field of numericFields) {
    if (!Number.isFinite(m[field])) {
        return reject("Metric tidak valid: " + field);
    }
}

if (typeof m.door_open !== "boolean") {
    return reject("door_open harus boolean");
}

// 8. Siapkan fields InfluxDB
const fields = {
    temp_c: m.temp_c,
    humidity_pct: m.humidity_pct,
    door_open: m.door_open,
    battery_pct: m.battery_pct,
    rssi_dbm: m.rssi_dbm
};

// 9. Validasi setpoint opsional
if (m.setpoint_c !== undefined) {
    if (
        !Number.isFinite(m.setpoint_c) ||
        m.setpoint_c < 0 ||
        m.setpoint_c > 10
    ) {
        return reject("Setpoint tidak valid");
    }

    fields.setpoint_c = m.setpoint_c;
}

// 10. Siapkan data InfluxDB
msg.measurement = "telemetry";

msg.payload = [
    fields,
    {
        device_id: data.device_id,
        domain: data.domain,
        gedung: data.gedung,
        ruang: data.ruang
    }
];

msg.timestamp = data.ts;

return msg;

const data = msg.payload;

if (!data || !data.device_id || !data.status) {
    return null;
}

if (!["online", "offline"].includes(data.status)) {
    return null;
}

msg.headers = {
    "Content-Type": "application/json",
    "X-API-Key": env.get("API_KEY")
};

msg.payload = {
    device_id: data.device_id,
    status: data.status,
    ts: data.ts || Date.now()
};

return msg;

const registry = {
    "cc-01": "gudang-a",
    "cc-02": "gudang-a",
    "cc-03": "gudang-b"
};

const now = Date.now();
let states = context.get("states") || {};

for (const id of Object.keys(registry)) {
    if (!states[id]) {
        states[id] = {
            last: now,
            rules: {}
        };
    }
}

const rules = [
    "TEMP_WARN",
    "TEMP_HIGH",
    "TEMP_ESCALATED",
    "DOOR_OPEN_LONG",
    "OFFLINE"
];

function slot(s, k) {
    return s.rules[k] || (
        s.rules[k] = {
            since: null,
            applied: null,
            pending: null,
            retry: 0
        }
    );
}

function reject(reason) {
    node.warn("Telemetry ditolak: " + reason);
    return null;
}

// =========================
// API RESPONSE HANDLER
// =========================

if (msg.result) {
    const q = msg.result;
    const s = states[q.id];

    if (s) {
        const a = slot(s, q.rule);

        if (a.pending && a.pending.token === q.token) {
            a.pending = null;

            if (q.ok) {
                a.applied = q.desired;
            } else {
                a.retry = now + 5000;
            }
        }
    }

} else if (msg.topic !== "watchdog") {

    // =========================
    // TELEMETRY VALIDATION
    // =========================

    const p = msg.payload;

    if (!p || typeof p !== "object") {
        return reject("Payload tidak valid");
    }

    if (p.schema !== "kampus.telemetry.v1") {
        return reject("Schema tidak dikenal");
    }

    if (!Object.prototype.hasOwnProperty.call(
        registry, p.device_id
    )) {
        return reject("Device tidak terdaftar");
    }

    if (
        p.domain !== "coldchain" ||
        p.gedung !== "bsd-a" ||
        p.ruang !== registry[p.device_id]
    ) {
        return reject("Lokasi tidak sesuai registry");
    }

    const expectedTopic =
        `kampus/coldchain/bsd-a/${p.ruang}/${p.device_id}/telemetry`;

    if (msg.topic !== expectedTopic) {
        return reject("MQTT topic tidak sesuai");
    }

    if (
        !Number.isSafeInteger(p.ts) ||
        p.ts <= 0
    ) {
        return reject("Timestamp tidak valid");
    }

    const m = p.metrics;

    if (!m || typeof m !== "object") {
        return reject("Metrics tidak tersedia");
    }

    const numericFields = [
        "temp_c",
        "humidity_pct",
        "battery_pct",
        "rssi_dbm"
    ];

    for (const field of numericFields) {
        if (!Number.isFinite(m[field])) {
            return reject("Metric tidak valid: " + field);
        }
    }

    if (typeof m.door_open !== "boolean") {
        return reject("door_open harus boolean");
    }

    if (m.setpoint_c !== undefined) {
        if (
            !Number.isFinite(m.setpoint_c) ||
            m.setpoint_c < 0 ||
            m.setpoint_c > 10
        ) {
            return reject("Setpoint tidak valid");
        }
    }

    // =========================
    // UPDATE DEVICE STATE
    // =========================

    const s = states[p.device_id];

    if (now - s.last >= 60000) {
        for (const k of rules.slice(0, 4)) {
            slot(s, k).since = null;
        }
    }

    s.last = now;
    s.metrics = m;

    if (m.temp_c > 8) {
        slot(s, "TEMP_ESCALATED").applied = null;
    }

    for (const [k, on] of [
        ["TEMP_WARN", m.temp_c > 6],
        ["TEMP_HIGH", m.temp_c > 8],
        ["DOOR_OPEN_LONG", m.door_open]
    ]) {
        const a = slot(s, k);
        a.since = on ? (a.since ?? now) : null;
    }
}

// =========================
// RULE EVALUATION
// =========================

const out = [];

for (const [id, s] of Object.entries(states)) {

    const stale = now - s.last >= 60000;

    for (const k of rules) {

        const a = slot(s, k);
        let desired;

        if (k === "OFFLINE") {

            desired = stale;

        } else if (stale || !s.metrics) {

            continue;

        } else if (k === "TEMP_ESCALATED") {

            if (s.metrics.temp_c > 8) {
                continue;
            }

            desired = false;

        } else {

            const duration =
                k === "TEMP_HIGH" ? 120000 : 60000;

            if (
                a.since !== null &&
                now - a.since < duration
            ) {
                continue;
            }

            desired = a.since !== null;
        }

        if (
            a.pending ||
            now < a.retry ||
            a.applied === desired
        ) {
            continue;
        }

        const token = (context.get("seq") || 0) + 1;

        context.set("seq", token);

        a.pending = { token };

        const source =
            k === "OFFLINE" ? "?source=no_data" : "";

        const severity =
            ["OFFLINE", "TEMP_HIGH"].includes(k)
                ? "critical"
                : "warning";

        const metadata = {
            source: k === "OFFLINE"
                ? "no_data"
                : "rule_engine",

            duration_seconds:
                k === "TEMP_HIGH" ? 120 : 60
        };

        if (s.metrics) {
            metadata.temp_c = s.metrics.temp_c;
            metadata.door_open = s.metrics.door_open;
        }

        out.push({
            method: "POST",

            url: desired
                ? "http://backend:8000/api/v1/internal/alerts"
                : `http://backend:8000/api/v1/internal/alerts/resolve-type/${id}/${k}${source}`,

            headers: {
                "Content-Type": "application/json",
                "X-API-Key": env.get("API_KEY")
            },

            requestTimeout: 10000,

            payload: desired
                ? {
                    device_id: id,
                    alert_type: k,
                    severity: severity,
                    message: `${k}: ${id}`,
                    metadata: metadata
                }
                : {},

            job: {
                id,
                rule: k,
                desired,
                token
            }
        });
    }
}

context.set("states", states);

return [out];

