const data = msg.payload;

// Validasi telemetry
if (!data || !data.metrics || !data.device_id) {
    node.warn("Data telemetry tidak valid");
    return null;
}

const deviceId = data.device_id;
const temp = Number(data.metrics.temp_c);

if (!Number.isFinite(temp)) {
    node.warn("Nilai suhu tidak valid");
    return null;
}

// Status baru V3
let states = flow.get("temperatureAlertStatesV3") || {};

let state = states[deviceId] || {
    warningSent: false,
    warningPending: false,
    highSent: false,
    highPending: false,
    highSince: null
};

const now = Date.now();

// Suhu normal: reset status
if (temp <= 6) {
    states[deviceId] = {
        warningSent: false,
        warningPending: false,
        highSent: false,
        highPending: false,
        highSince: null
    };

    flow.set("temperatureAlertStatesV3", states);
    node.warn("SUHU NORMAL: " + deviceId);
    return null;
}

// Mulai hitung durasi suhu tinggi
if (temp > 8) {
    if (state.highSince === null) {
        state.highSince = now;
    }
} else {
    state.highSince = null;
    state.highSent = false;
    state.highPending = false;
}

// TEMP_WARN: suhu > 6°C
if (!state.warningSent && !state.warningPending) {
    state.warningPending = true;

    states[deviceId] = state;
    flow.set("temperatureAlertStatesV3", states);

    node.warn("MENGIRIM TEMP_WARN: " + deviceId);

    msg.method = "POST";
    msg.url = "http://backend:8000/api/v1/internal/alerts";
    msg.alertDeviceId = deviceId;
    msg.alertType = "TEMP_WARN";

    msg.payload = {
        device_id: deviceId,
        alert_type: "TEMP_WARN",
        severity: "warning",
        message: `Suhu ${temp.toFixed(2)}°C melebihi batas 6°C`,
        metadata: {
            temp_c: temp,
            threshold_c: 6
        }
    };

    return msg;
}

// TEMP_HIGH: suhu > 8°C selama 2 menit
if (
    temp > 8 &&
    state.highSince !== null &&
    !state.highSent &&
    !state.highPending &&
    now - state.highSince >= 120000
) {
    state.highPending = true;

    states[deviceId] = state;
    flow.set("temperatureAlertStatesV3", states);

    node.warn("MENGIRIM TEMP_HIGH: " + deviceId);

    msg.method = "POST";
    msg.url = "http://backend:8000/api/v1/internal/alerts";
    msg.alertDeviceId = deviceId;
    msg.alertType = "TEMP_HIGH";

    msg.payload = {
        device_id: deviceId,
        alert_type: "TEMP_HIGH",
        severity: "critical",
        message: `Suhu ${temp.toFixed(2)}°C melebihi batas 8°C selama 2 menit`,
        metadata: {
            temp_c: temp,
            threshold_c: 8,
            duration_seconds: 120
        }
    };

    return msg;
}

// Simpan status
states[deviceId] = state;
flow.set("temperatureAlertStatesV3", states);

return null;

const data = msg.payload;

if (!data || !data.metrics || !data.device_id) {
    return null;
}

const deviceId = data.device_id;
